mapper.select:
SELECT s.ID, s.SOURCE_ID, s.COLLECTION_NAME, s.DIMENSION, s.DISTANCE_METRIC, s.METADATA_SCHEMA, s.INSTANCE_KEY, s.CREATE_TIME, s.UPDATE_TIME, s.CREATE_USER, s.UPDATE_USER, s.ENV_CODE, src.NAME AS SOURCE_NAME, src.PROVIDER AS SOURCE_PROVIDER, inst.INSTANCE_NAME FROM AI_VEC_STORE s LEFT JOIN AI_VEC_SOURCE src ON s.SOURCE_ID = src.ID AND src.DELETED = 0 LEFT JOIN AI_INSTANCE inst ON s.INSTANCE_KEY = inst.INSTANCE_KEY AND inst.DELETED = 0 WHERE s.deleted = 0
AND s.SOURCE_ID = #{req.sourceId}
AND s.COLLECTION_NAME LIKE CONCAT('%', #{req.collectionName}, '%')
AND s.INSTANCE_KEY = #{req.instanceKey}
AND s.ENV_CODE = #{req.envCode}
AND s.CREATE_USER = #{req.createUser}
ORDER BY s.CREATE_TIME DESC
